//! The uniform response envelope. Every endpoint answers with
//! `{"data":…,"meta":{…}}` or `{"error":{code,message},"meta":{…}}` so the
//! dashboard never has to special-case a route to find out what went wrong.

use axum::extract::FromRequestParts;
use axum::http::request::Parts;
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde_json::{json, Value};

use crate::app::AppState;
use aerona_core::error::Error;
use aerona_core::time::now;

/// Per-request id, generated by the `identify` layer and returned in the
/// `X-Request-Id` response header. It is deliberately *not* in the JSON body:
/// putting it there would mean every handler has to receive it, and a header is
/// where the dashboard's error toast and `main.py`'s log line can both find it.
pub const REQUEST_ID_HEADER: &str = "x-request-id";
#[derive(Debug, Clone)]
pub struct RequestId(pub String);

impl<S> FromRequestParts<S> for RequestId
where
    S: Send + Sync,
{
    type Rejection = std::convert::Infallible;

    async fn from_request_parts(
        parts: &mut Parts,
        _state: &S,
    ) -> std::result::Result<Self, Self::Rejection> {
        Ok(parts
            .extensions
            .get::<RequestId>()
            .cloned()
            .unwrap_or(RequestId(String::new())))
    }
}

fn meta() -> Value {
    json!({ "apiVersion": aerona_core::API_VERSION, "at": now() })
}

pub fn ok(data: Value) -> Response {
    (
        StatusCode::OK,
        Json(json!({ "data": data, "meta": meta() })),
    )
        .into_response()
}

pub fn with_status(resp: Response, status: StatusCode) -> Response {
    let mut resp = resp;
    *resp.status_mut() = status;
    resp
}

pub fn created(data: Value) -> Response {
    with_status(ok(data), StatusCode::CREATED)
}

/// `202` + a pollable id: how every Discord-facing mutation answers, because the
/// gateway worker performs the action after us.
pub fn accepted(outbox_id: i64) -> Response {
    with_status(
        ok(json!({ "id": outbox_id, "poll": format!("/api/v1/outbox/{outbox_id}") })),
        StatusCode::ACCEPTED,
    )
}

/// `204` with no body — for DELETE-style routes where the dashboard only needs
/// to know it worked.
pub fn no_content() -> Response {
    StatusCode::NO_CONTENT.into_response()
}

/// The one place that decides what a client may learn about a failure.
pub fn error_response(err: &Error) -> Response {
    let status = StatusCode::from_u16(err.status()).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let mut error = json!({
        "code": err.code(),
        // `safe_message` is the only text allowed out: never a path, a SQL
        // fragment, or an upstream response body.
        "message": err.safe_message(),
    });
    if let Some(details) = validation_details(err) {
        error["details"] = details;
        // Otherwise the message and the details are the same blob twice; the fields
        // belong in `details`, so `message` stays a sentence.
        error["message"] = json!("one or more fields are invalid");
    }
    if err.status() >= 500 {
        // The full text goes to the log, never to the wire.
        tracing::error!(%err, code = err.code(), "request failed");
    } else {
        tracing::debug!(code = err.code(), "request rejected");
    }
    (status, Json(json!({ "error": error, "meta": meta() }))).into_response()
}

/// A handler error with field-level detail.
///
/// One field on purpose: handlers write `Invalid(Error::Invalid(..))` and `?`
/// converts anything else, so there is exactly one path from an internal error to
/// the wire. `details` rides along as a json object inside `Error::Invalid`, which
/// is the shape [`validation_details`] reads back out.
#[derive(Debug)]
pub struct Invalid(pub Error);

impl Invalid {
    /// A validation failure naming the offending fields. The client sees
    /// `details: {field: reason}` plus a generic message — never an echo of what it
    /// submitted, which here is often somebody else's id.
    pub fn new(err: Error, fields: Vec<(&'static str, &'static str)>) -> Self {
        if fields.is_empty() {
            return Invalid(err);
        }
        let mut merged = match &err {
            Error::Invalid(why) if why.starts_with('{') => serde_json::from_str::<Value>(why)
                .ok()
                .and_then(|v| v.as_object().cloned())
                .unwrap_or_default(),
            _ => serde_json::Map::new(),
        };
        for (k, v) in fields {
            merged.insert(k.to_string(), Value::String(v.to_string()));
        }
        Invalid(Error::Invalid(Value::Object(merged).to_string()))
    }

    /// The common case: one field, one reason.
    pub fn field(key: &'static str, reason: &'static str) -> Self {
        Invalid::new(
            Error::Invalid(format!("{key}: {reason}")),
            vec![(key, reason)],
        )
    }
}

impl From<Error> for Invalid {
    fn from(e: Error) -> Self {
        Invalid(e)
    }
}

impl IntoResponse for Invalid {
    fn into_response(self) -> Response {
        // Everything about the shape of a failure lives in `error_response`; this is
        // a pass-through so a handler can return `Err(e.into())` from any `?`.
        error_response(&self.0)
    }
}

/// An error whose message is a JSON object is rendered as `error.details` as
/// well as `error.message`, so the dashboard can highlight the offending fields
/// without parsing prose.
fn validation_details(err: &Error) -> Option<Value> {
    match err {
        Error::Invalid(why) if why.starts_with('{') => serde_json::from_str(why).ok(),
        _ => None,
    }
}

/// Small helper so handlers can `?` a `std::result::Result<Value, Error>` and answer directly.
pub fn data(v: Value) -> Response {
    ok(v)
}

/// A JSON body that rejects *through the envelope*.
///
/// `axum::Json` would answer a malformed body with its own plain-text 400, so the
/// dashboard would have to understand two error shapes. This one also enforces the
/// "must be an object" rule that every mutating route in this API assumes.
pub struct JsonBody(pub Value);

impl JsonBody {
    pub fn get(&self) -> &Value {
        &self.0
    }
}

impl axum::extract::FromRequest<AppState> for JsonBody {
    type Rejection = Invalid;

    async fn from_request(
        req: axum::extract::Request,
        _state: &AppState,
    ) -> std::result::Result<Self, Self::Rejection> {
        // The limit is enforced here as well as by the body-limit layer: `to_bytes`
        // is the only place that can say "too large" *before* we parse it.
        // Read the declared length first: `into_body` moves the request.
        let declared = declared_length(&req);
        let bytes = match axum::body::to_bytes(req.into_body(), crate::app::MAX_BODY_BYTES).await {
            Ok(b) => b,
            // `to_bytes` collapses "over the limit" and "the connection dropped" into
            // one error; the declared length says which it was, and the client
            // deserves the difference (413: send less; 400: malformed).
            Err(_) => {
                return Err(Invalid(match declared {
                    Some(n) if n > crate::app::MAX_BODY_BYTES => Error::PayloadTooLarge,
                    _ => Error::Invalid("request body could not be read".into()),
                }))
            }
        };
        if bytes.is_empty() {
            return Ok(JsonBody(Value::Object(serde_json::Map::new())));
        }
        let value: Value = serde_json::from_slice(&bytes).map_err(|e| {
            Invalid(Error::Invalid(format!(
                "body must be valid json: {}",
                short(&e.to_string())
            )))
        })?;
        if !value.is_object() {
            return Err(Invalid(Error::Invalid("body must be a json object".into())));
        }
        Ok(JsonBody(value))
    }
}

fn declared_length(req: &axum::extract::Request) -> Option<usize> {
    req.headers()
        .get(axum::http::header::CONTENT_LENGTH)?
        .to_str()
        .ok()?
        .parse()
        .ok()
}

/// Truncate a parser message before it reaches the wire.
fn short(s: &str) -> String {
    s.chars().take(180).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    // Reading a body needs the runtime, so the assertion helpers here are async: the
    // alternative (a manual `block_on`) would hide that a handler's body is streamed.
    async fn body_of(resp: Response) -> Value {
        let bytes = axum::body::to_bytes(resp.into_body(), 1 << 20)
            .await
            .unwrap();
        serde_json::from_slice(&bytes).unwrap()
    }

    #[tokio::test]
    async fn ok_envelope_has_data_and_meta() {
        let resp = ok(json!({"hello": "world"}));
        assert_eq!(resp.status(), StatusCode::OK);
        let body = body_of(resp).await;
        assert_eq!(body["data"]["hello"], "world");
        assert_eq!(body["meta"]["apiVersion"], aerona_core::API_VERSION);
        assert!(body["meta"]["at"].as_i64().unwrap() > 0);
        assert!(
            body.get("error").is_none(),
            "success must not carry an error key"
        );
    }

    #[tokio::test]
    async fn created_and_accepted_shift_the_status_only() {
        let c = created(json!({"id": 3}));
        assert_eq!(c.status(), StatusCode::CREATED);
        assert_eq!(body_of(c).await["data"]["id"], 3);
        let a = accepted(9);
        assert_eq!(a.status(), StatusCode::ACCEPTED);
        let body = body_of(a).await;
        assert_eq!(body["data"]["id"], 9);
        assert_eq!(body["data"]["poll"], "/api/v1/outbox/9");
        assert_eq!(no_content().status(), StatusCode::NO_CONTENT);
    }

    #[tokio::test]
    async fn errors_keep_status_code_and_never_leak_internals() {
        // A DB error text contains a path; the client must see only the code.
        let resp = error_response(&Error::Db(
            "/home/operator/aerona/data/aerona.db: no such table: warns".into(),
        ));
        assert_eq!(resp.status(), StatusCode::INTERNAL_SERVER_ERROR);
        let body = body_of(resp).await;
        assert_eq!(body["error"]["code"], "internal");
        let msg = body["error"]["message"].as_str().unwrap();
        assert!(!msg.contains("aerona.db"), "leaked a path into {msg}");
        assert!(
            !msg.contains("no such table"),
            "leaked SQL detail into {msg}"
        );

        let nf = error_response(&Error::NotFound("ticket"));
        assert_eq!(nf.status(), StatusCode::NOT_FOUND);
        assert_eq!(body_of(nf).await["error"]["code"], "not_found");

        assert_eq!(
            error_response(&Error::RateLimited).status(),
            StatusCode::TOO_MANY_REQUESTS
        );
        assert_eq!(
            error_response(&Error::Unauthorized).status(),
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(
            error_response(&Error::Forbidden("nope")).status(),
            StatusCode::FORBIDDEN
        );
        assert_eq!(
            error_response(&Error::Conflict("dup".into())).status(),
            StatusCode::CONFLICT
        );
        assert_eq!(
            error_response(&Error::Discord {
                status: 403,
                message: "Missing Permissions".into()
            })
            .status(),
            StatusCode::FORBIDDEN
        );
    }

    #[tokio::test]
    async fn invalid_carries_field_details_without_changing_the_shape() {
        let resp = Invalid::new(Error::Invalid("bad".into()), vec![("reason", "required")])
            .into_response();
        assert_eq!(resp.status(), StatusCode::BAD_REQUEST);
        let body = body_of(resp).await;
        assert_eq!(body["error"]["code"], "bad_request");
        assert_eq!(
            body["error"]["message"], "one or more fields are invalid",
            "the payload is never echoed back"
        );
        assert_eq!(body["error"]["details"]["reason"], "required");
    }

    #[tokio::test]
    async fn data_helper_is_the_success_shape() {
        assert_eq!(body_of(data(json!({"a": 1}))).await["data"]["a"], 1);
    }
}
